const r = await tools.write({path:"src/index.mjs",content:`export function union(intervals) {
  if (!Array.isArray(intervals)) {
    throw new TypeError('intervals must be an array');
  }

  const sorted = intervals.map((interval) => {
    if (interval === null || typeof interval !== 'object') {
      throw new TypeError('each interval must be an object');
    }

    const { start, end } = interval;
    if (!Number.isFinite(start) || !Number.isFinite(end)) {
      throw new TypeError('interval start and end must be finite numbers');
    }
    if (end < start) {
      throw new RangeError('interval end must not be less than start');
    }

    return { interval, start, end };
  });

  sorted.sort((a, b) => {
    if (a.start !== b.start) return a.start < b.start ? -1 : 1;
    if (a.end !== b.end) return a.end < b.end ? -1 : 1;
    return 0;
  });

  const result = [];
  for (const current of sorted) {
    if (current.start === current.end) continue;

    const previous = result[result.length - 1];
    if (previous && current.start <= previous.end) {
      if (current.end > previous.end) {
        previous.end = current.end;
        previous.interval.end = current.end;
      }
    } else {
      result.push({
        start: current.start,
        end: current.end,
        interval: current.interval,
      });
    }
  }

  return result.map(({ interval }) => interval);
}
`});
